import { newId, CATALOG, PACKS, PROVIDERS, LIMITS, LABELS, createState, dispatch, validateState, restoreBackup, withSamples, makeHandoff, makeLocalBrief, normalizeResult, exportTask, SYSTEM_PROMPT } from './core.mjs';
const edition=document.documentElement.dataset.edition||'chatgpt', provider=PROVIDERS[edition];
const key=`skill-switchboard:${edition}:v1`, $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={board:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',inbox:'M4 4h16l2 12v4H2v-4L4 4z M3 15h5l2 3h4l2-3h5',mail:'M3 5h18v14H3z M3 6l9 7 9-7',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 11h16',flag:'M5 22V3 M5 4c6-5 9 5 15 0v10c-6 5-9-5-15 0',fork:'M7 3v5c0 4 10 4 10 8v5 M7 8v13 M14 5l3-3 3 3 M17 2v6',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',code:'M8 5l-6 7 6 7 M16 5l6 7-6 7 M14 3l-4 18',people:'M16 21v-3c0-5-13-5-13 0v3 M9.5 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M17 4c5 0 5 7 0 7 M19 14c3 1 3 4 3 7',link:'M9 15l6-6 M8 8l3-3c5-5 12 2 7 7l-3 3 M16 16l-3 3c-5 5-12-2-7-7l3-3',pen:'M3 21l5-1L21 7l-4-4L4 16z M14 6l4 4',chart:'M3 3v18h18 M7 16v-4 M12 16V7 M17 16v-7',bug:'M8 6l-2-3 M16 6l2-3 M3 10h4 M17 10h4 M3 17h4 M17 17h4 M7 9c0-6 10-6 10 0v8c0 6-10 6-10 0z M12 10v10',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h1 M3 12h1 M3 19h1',clock:'M12 8v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 4v16 M4 12h16',arrow:'M4 12h16 M14 6l6 6-6 6',check:'M4 12l5 5L20 6',close:'M5 5l14 14 M5 19L19 5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',copy:'M8 8h13v13H8z M16 8V3H3v13h5',help:'M9 8c0-4 7-4 7 0 0 3-4 3-4 6 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.board}"/></svg>`;
const mark='<span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>';
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const field=(label,name,value='',opts='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${opts}></label>`;
let state=createState(), recoveryRaw='', memoryOnly=false, changedElsewhere=false;
try {const raw=localStorage.getItem(key);if(raw){try{state=validateState(JSON.parse(raw));}catch{recoveryRaw=raw;}}}catch{memoryOnly=true;}
let view='board', filter='open', query='', focused=null, api={configured:false}, csrf='', busy=null, compact=false;
const active=t=>t.status!=='closed', waiting=t=>['review','triage','blocked'].includes(t.status);
const skillFor=t=>state.skills.find(s=>s.id===t.skillId);
const findTask=id=>state.tasks.find(t=>t.id===id);
const stamp=at=>new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(at));
function toast(message,error=false){const inDialog=$('#dialog[open] .dialog-message');if(inDialog){inDialog.textContent=message;inDialog.className='dialog-message'+(error?' error':'');}const el=$('#toast');el.textContent=message;el.className=`toast visible ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),6500);}
async function commit(change){
 if(recoveryRaw)throw new Error('Recover or explicitly reset the damaged local data first.');
 const apply=async()=>{if(!memoryOnly){const raw=localStorage.getItem(key);if(raw){let stored;try{stored=validateState(JSON.parse(raw));}catch{throw new Error('Stored data changed or is damaged. Export before reloading.');}if(stored.revision!==state.revision)throw new Error('Another tab changed this board. Use Reload latest before saving. Your current edits have not been applied.');}else if(state.revision>0)throw new Error('This board was reset in another tab. Reload latest before saving.');}
  const next=typeof change==='function'?change(state):dispatch(state,change);validateState(next);
  if(!memoryOnly){try{localStorage.setItem(key,JSON.stringify(next));}catch{throw new Error('The browser could not save this change. Export a backup and free storage. Your previous board is intact.');}}
  state=next;changedElsewhere=false;render();return next;};
 return navigator.locks? navigator.locks.request(key,apply):apply();
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Copied. You decide where it goes next.');}catch{showDialog('Copy this text',`<p>Clipboard permission was unavailable. Select and copy the text below.</p><textarea class="code-text" aria-label="Text to copy" readonly>${esc(value)}</textarea>${focused?button('Back to task','task',focused,'secondary'):''}`,false);$('.code-text').select();}}
function stat(label,value,caption){return `<div class="stat"><div><span>${label}</span><strong>${value}</strong></div><small>${caption}</small></div>`;}
function banner(){const el=$('#banner');el.innerHTML=recoveryRaw?`<div class="notice danger">Your saved board could not be read. It has not been overwritten. ${button('Download raw recovery','recovery-download')} ${button('Reset damaged storage','reset')}</div>`:memoryOnly?'<div class="notice">Storage is unavailable in this browser. Work is temporary; export before closing.</div>':changedElsewhere?`<div class="notice">This board changed in another tab. Keep any unsaved text before reloading. ${button('Reload latest','reload')}</div>`:'';}
function shell(){document.title=`Skill Switchboard for ${provider.name}`;$('#app').innerHTML=`<a class="skip" href="#main">Skip to workspace</a><aside class="sidebar"><a class="brand" href="../index.html" aria-label="Skill Switchboard editions">${mark}<span>Skill<br>Switchboard</span></a><div class="edition-tag">for ${provider.name}<span>COMPANION</span></div><nav aria-label="Workspace">${[['board','board','Switchboard'],['inbox','inbox','Inbox'],['people','people','People'],['activity','clock','Activity']].map(([id,ic,label])=>button(`${icon(ic)}<span>${label}</span>${id==='inbox'?'<b id="inbox-count"></b>':''}`,'view',id,`nav-item ${view===id?'selected':''}`)).join('')}</nav><div class="sidebar-bottom"><div class="privacy-note">${icon('shield')}<div><strong>Your work. Your call.</strong><small>Local by default.<br>No silent actions.</small></div></div>${button(`${icon('settings')} Setup & data`,'view','setup','nav-item')}${button(`${icon('help')} Quick guide`,'guide','','nav-item')}<small class="independent">Independent open-source project.<br>Not made or endorsed by ${provider.company}.</small></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">Personal workspace <span>/</span> <strong id="page-name">Switchboard</strong></span><div class="top-actions"><span class="local-indicator">● Local workspace</span>${button(`${icon('plus')} Capture work`,'capture','','primary small')}</div></header><div id="banner"></div><main id="main" tabindex="-1"></main><footer class="workspace-footer"><span>Drafts stay drafts. External actions stay yours.</span><span>Skill Switchboard · v1.1</span></footer></div><dialog id="dialog" aria-labelledby="dialog-title"></dialog><div id="toast" class="toast" role="status" aria-live="polite"></div><input id="file-input" type="file" accept=".txt,.md,.json,text/plain,application/json" hidden>`;
 $('#dialog').addEventListener('close',()=>{if(!$('#dialog').open)focused=null;});
}
function render(){
 if(!$('#app').children.length)shell();banner();
 document.querySelectorAll('.nav-item[data-action="view"]').forEach(el=>el.classList.toggle('selected',el.dataset.id===view));
 $('#inbox-count').textContent=state.tasks.filter(t=>t.status==='triage').length||'';
 $('#page-name').textContent={board:'Switchboard',inbox:'Inbox',people:'People',activity:'Activity',setup:'Setup & data'}[view];
 const main=$('#main');if(view==='board')main.innerHTML=board();if(view==='inbox')main.innerHTML=inbox();if(view==='people')main.innerHTML=people();if(view==='activity')main.innerHTML=activity();if(view==='setup')main.innerHTML=setup();
}
function board(){const need=state.tasks.filter(waiting), ready=state.tasks.filter(t=>t.status==='ready'), approved=state.tasks.filter(t=>t.status==='approved');return `<section class="hero"><div><div class="eyebrow">A LITTLE LESS OVERWHELM</div><h1>Clear the noise.<br><em>Keep the judgment.</em></h1><p>Give incoming work a place to land.<br>Tasks move. Skills stay put. You make the call.</p></div><div class="hero-art"><img src="./assets/hero.webp" alt="Sculptural tiles turning scattered inputs into one deliberate choice" width="1376" height="768"><div class="art-caption"><span class="tiny-mark">✦</span> Many capabilities. One clear next step.</div></div></section><section class="stats" aria-label="Workspace status">${stat('Your next decisions',need.length,'Review, route, or unblock')}${stat('Ready to prepare',ready.length,'Waiting for your direction')}${stat('Approved drafts',approved.length,'Prepared here. Not sent.')}</section><section class="board-section"><div class="section-heading"><div><h2>Your skills <span class="quiet">${state.skills.length} / 24 board slots</span></h2><p>Stable skill stations. Tasks move into them; your decisions stay with the task.</p></div><div class="inline-actions">${button(compact?'Comfortable view':'Compact view','compact','','subtle')}${button(`${icon('plus')} Add skill`,'skills','','secondary small')}</div></div><div class="board-layout"><div class="skill-grid ${compact?'compact':''}">${state.skills.map(tile).join('')}</div><aside class="next-panel"><div class="panel-heading"><span class="eyebrow">NEXT DECISIONS</span>${icon('fork')}</div>${need.length?need.sort((a,b)=>(b.priority==='high')-(a.priority==='high')||a.createdAt.localeCompare(b.createdAt)).slice(0,4).map(t=>`<button class="decision-row" data-action="task" data-id="${t.id}"><span class="status-dot ${t.status}"></span><span><strong>${esc(t.title)}</strong><small>${LABELS[t.status]} · ${esc(skillFor(t)?.name||'Unrouted')}</small></span>${icon('arrow')}</button>`).join(''):`<div class="calm-empty">${icon('check')}<h3>A little breathing room.</h3><p>No decisions are waiting. Capture something new, or prepare work already on your board.</p></div>`}<div class="panel-tip"><strong>Tasks move. Skills stay put.</strong><p>When more than one skill fits, the task waits for you instead of guessing.</p></div></aside></div></section>${!state.tasks.length?`<section class="empty-start"><span>${icon('inbox')}</span><div><h3>A clean slate, not an empty prompt.</h3><p>Paste one message or drop a text file. We will help you choose the next step.</p></div>${button('Capture your first task','capture','','primary')}</section>`:''}`;}
function tile(s){const ts=state.tasks.filter(t=>t.skillId===s.id&&active(t)), review=ts.filter(t=>t.status==='review').length, help=ts.filter(t=>t.status==='blocked').length, last=state.audit.find(a=>ts.some(t=>t.id===a.taskId));const label=review?`${review} to review`:help?`${help} need help`:ts.length?`${ts.length} open`:'Ready when you are';return `<button class="skill-tile ${review?'has-attention':''} ${s.enabled?'':'paused'}" data-action="tile" data-id="${s.id}" aria-label="${esc(s.name)}: ${label}${s.enabled?'':', paused'}"><div class="tile-top"><span class="skill-icon">${icon(s.icon)}</span><span class="skill-state ${review?'attention':''}">${review?'<span class="status-dot review"></span> ':''}${s.enabled?(review?`${review} review`:ts.length?`${ts.length} open`:'Idle'):'Paused'}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="tile-bottom"><span>${review?'Your judgment is next':ts.length?'Open the queue':'Draft-only skill'}</span>${icon('arrow')}</div>${last?`<div class="tile-activity">Last activity ${esc(stamp(last.at))}</div>`:''}</button>`;}
function taskList(tasks){return tasks.length?`<div class="task-list">${tasks.map(t=>`<button class="task-row" data-action="task" data-id="${t.id}"><span class="row-icon">${icon(skillFor(t)?.icon||'inbox')}</span><span class="task-description"><strong>${esc(t.title)} ${t.sample?'<span class="sample">SAMPLE</span>':''}</strong><small>${esc(skillFor(t)?.name||'Manual triage')}${t.journey?.length?' · '+(t.journey.length+1)+' skills':''} · ${esc(t.source)}${t.ownerId?' · '+esc(state.people.find(p=>p.id===t.ownerId)?.name):''}${t.dueDate?' · Due '+esc(t.dueDate):''}</small></span><span class="status-pill ${t.status}">${LABELS[t.status]}</span>${icon('arrow')}</button>`).join('')}</div>`:`<div class="large-empty">${icon('inbox')}<h3>Nothing in this view.</h3><p>Capture work, change the filter, or clear your search.</p></div>`;}
function journeyStrip(t){if(!t.journey?.length)return '';const current=skillFor(t);return `<div class="journey-strip" aria-label="Task journey"><span class="journey-label">Task journey</span>${t.journey.map(stage=>`<span class="journey-stage done">${icon('check')} ${esc(stage.skillName)}</span><span class="journey-arrow">›</span>`).join('')}<span class="journey-stage current">${esc(current?.name||'Unrouted')}</span></div>`;}
function inbox(){const tasks=state.tasks.filter(t=>(filter==='all'||filter==='open'&&active(t)||filter===t.status)&&`${t.title} ${t.body} ${skillFor(t)?.name||''}`.toLowerCase().includes(query.toLowerCase()));return `<section class="page-intro"><div class="eyebrow">ONE PLACE TO LAND</div><h1>Your inbox, with a next step.</h1><p>Route the uncertain work. Review the prepared work. Leave with less in your head.</p></section><div class="inbox-toolbar"><div class="filters" role="group" aria-label="Task status filter">${[['open','Open'],['triage','Needs routing'],['review','Review'],['approved','Approved'],['closed','Closed'],['all','All']].map(([id,label])=>button(label,'filter',id,filter===id?'active':'')).join('')}</div><label class="search-field">${icon('search')}<input id="task-search" aria-label="Search tasks" type="search" value="${esc(query)}" placeholder="Find work…"></label></div><p class="result-count">${tasks.length} task${tasks.length===1?'':'s'} · Local workspace</p>${taskList(tasks)}`;}
function people(){return `<section class="page-intro"><div class="eyebrow">CONTEXT, NOT ANOTHER ADDRESS BOOK</div><h1>Know who belongs in the loop.</h1><p>Keep responsibilities close to the work. These are private notes, not invitations or assigned tickets.</p>${button(`${icon('plus')} Add person`,'person','','primary')}</section><div class="people-grid">${state.people.length?state.people.map(p=>`<article class="person-card"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><h2>${esc(p.name)}</h2><strong>${esc(p.role||'Role not specified')}</strong><p>${esc(p.context||'Add working context when it helps.')}</p><small>${state.tasks.filter(t=>t.ownerId===p.id&&active(t)).length} open tasks labeled for this person</small>${button('Remove local card','remove-person',p.id,'subtle')}</article>`).join(''):`<div class="large-empty">${icon('people')}<h3>The person behind the next step.</h3><p>Add a teammate and their responsibilities. Only a name is required.</p></div>`}</div>`;}
function activity(){return `<section class="page-intro"><div class="eyebrow">A RECORD, NOT A PERFORMANCE</div><h1>See what actually happened.</h1><p>Local decisions and preparation steps. This editable local history is not a tamper-proof compliance log.</p>${button(`${icon('download')} Export activity`,'export-audit','','secondary')}</section><ol class="timeline">${state.audit.length?state.audit.map(a=>`<li><span class="timeline-dot"></span><div><time>${esc(stamp(a.at))}</time><p>${esc(a.message)}</p>${a.taskId&&findTask(a.taskId)?button('Open task','task',a.taskId,'text-button'):''}</div></li>`).join(''):'<li>No activity yet. Your first capture will appear here.</li>'}</ol>`;}
function setup(){return `<section class="page-intro"><div class="eyebrow">START SIMPLE. STAY IN CONTROL.</div><h1>Your tools, on your terms.</h1><p>Companion mode works with your existing chat account. No subscription is treated as an API credit.</p></section><div class="setup-grid"><section class="setup-card"><span class="step-number">01</span><h2>Use your existing ${provider.name} chat</h2><p>Open a task, check what is safe to share, copy its prepared request, and paste it into ${provider.name}. Bring the draft back here for review.</p><a class="button primary" href="${provider.url}" target="_blank" rel="noopener noreferrer">Open ${provider.name} ${icon('arrow')}</a>${button('Download companion instructions','download-skill','','secondary')}<small>Opening the site does not transfer task data or connect an account. Optional skill installation depends on your provider and workspace.</small></section><section class="setup-card"><span class="step-number">02</span><h2>Optional direct API drafting</h2><span class="status-pill ${api.configured?'approved':'ready'}">${api.configured?'Server configured':'Not configured'}</span><p>${api.configured?`Model: ${esc(api.model)}. Requests are made only when you explicitly generate a draft.`:'Keep keys on your local Node server, never in this browser. Set the API key and model in .env, then restart npm start.'}</p><pre>${esc({chatgpt:'OPENAI_API_KEY=\nOPENAI_MODEL=',claude:'ANTHROPIC_API_KEY=\nANTHROPIC_MODEL=',gemini:'GEMINI_API_KEY=\nGEMINI_MODEL='}[edition])}</pre><small>Separate API billing and provider data policies apply. No paid request runs during setup. Static or downloaded HTML uses companion mode only.</small>${button('Recheck local server','check-api','','subtle')}</section><section class="setup-card"><span class="step-number">03</span><h2>Your data is yours</h2><p>Saved in this browser for this edition. No analytics, cloud sync, or shared team database. Backups contain your source text, drafts, and people notes; keep them private.</p><div class="inline-actions">${button(`${icon('download')} Export backup`,'export','','secondary')}${button('Restore backup','import','','secondary')}</div><small>Restoring replaces this local board after confirmation. Imported approvals need a new review and sharing resets to private.</small></section><section class="setup-card"><span class="step-number">04</span><h2>Make room for good work</h2><p>${state.skills.length}/24 board skill stations · ${state.tasks.length}/200 tasks · ${state.people.length}/40 people.<br>Export before removing anything you need to retain.</p>${button('Remove closed tasks','prune','','secondary')}${button('Reset this edition','reset','','danger-button')}<small>ChatGPT, Claude, and Gemini boards are separate. Move work deliberately using a backup; there is no invisible synchronization.</small></section></div>`;}
function showDialog(title,body,drawer=false){const d=$('#dialog');delete d.dataset.taskId;d.className=drawer?'drawer':'modal';d.innerHTML=`<div class="dialog-header"><div><span class="eyebrow">SKILL SWITCHBOARD</span><h2 id="dialog-title">${esc(title)}</h2></div>${button('<span class="sr-only">Close dialog</span>'+icon('close'),'dismiss','','icon-button')}</div><div class="dialog-body">${body}</div><div class="dialog-message" role="status" aria-live="polite"></div>`;if(!d.open)d.showModal();d.scrollTop=0;d.querySelector('button,input,textarea,select,a[href]')?.focus();}
function welcome(){showDialog('A calmer way to work with AI.',`<div class="welcome-art"><img src="./assets/hero.webp" alt="An orderly board of sculptural skill tiles" width="1376" height="768"></div><p class="welcome-lead">Capture the loose ends. Tasks move to stable skills. You decide what happens next.</p><div class="welcome-steps"><div><b>1</b><strong>Capture</strong><span>Paste a message or drop a text file.</span></div><div><b>2</b><strong>Prepare</strong><span>The task lands at one skill station.</span></div><div><b>3</b><strong>Review</strong><span>Approve, then move it onward if needed.</span></div></div><form data-form="onboard"><label class="field">Choose a starting set<select name="pack"><option value="everyday">Everyday work — replies, notes, issues, decisions</option><option value="delivery">Project delivery — coordination and dependencies</option><option value="maker">Maker — code, bugs, research, and content</option></select></label><div class="form-actions"><button class="primary" name="mode" value="sample" type="submit">Explore a sample board ${icon('arrow')}</button><button class="secondary" name="mode" value="empty" type="submit">Start with my work</button></div></form><p class="fine-print">No login. No API key. Fictional examples are labeled. Your browser stores your board; export a backup before clearing browser data.</p>`);}
function capture(prefill={}){showDialog('Give something a place to land.',`<form data-form="capture">${field('A short title','title',prefill.title||'','required maxlength="140" placeholder="What needs to move forward?"')}<label class="field">Source text<textarea name="body" required maxlength="12000" rows="7" placeholder="Paste a message, notes, a question, or a code diff…">${esc(prefill.body||'')}</textarea></label><div class="drop-zone" id="drop-zone" tabindex="0">${icon('download')} Drop a .txt or .md file here, or ${button('choose a file','text-file','','text-button')}<small>Plain text only · 12,000 characters · nothing uploaded</small></div><div class="form-grid">${field('Source label','source',prefill.source||'Pasted text','required maxlength="120"')}${field('Source link (optional)','sourceUrl','','type="url" placeholder="https://…"')}<label class="field">Route<select name="skillId"><option value="">Suggest with local rules</option>${state.skills.filter(s=>s.enabled).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label class="field">Priority<select name="priority"><option value="normal">Normal</option><option value="high">High — needs attention</option></select></label><label class="field">Owner label<select name="ownerId"><option value="">Unassigned</option>${state.people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>${field('Due date (optional)','dueDate','','type="date"')}</div><div class="notice">${icon('shield')} Private until you review it for sharing. Routing happens locally; no model is called.</div><div class="form-actions"><button class="primary" type="submit">Capture & route ${icon('arrow')}</button>${button('Cancel','dismiss','','secondary')}</div></form>`);}
function tileDrawer(id){const s=state.skills.find(s=>s.id===id);if(!s)return;showDialog(s.name,`<p class="drawer-lead">${esc(s.description)}</p><div class="skill-contract"><span class="eyebrow">STABLE SKILL STATION</span><p>${esc(s.instructions)}</p><div class="contract-facts"><p><strong>Use when</strong>${esc(s.useWhen)}</p><p><strong>Do not use when</strong>${esc(s.doNotUseWhen)}</p><p><strong>Output</strong>${esc(s.outputContract)}</p><p><strong>Effect boundary</strong>${s.effectClass==='prepare'?'Prepare only — no external action':esc(s.effectClass)}</p></div><small>Never: ${esc(s.negativeScope)}</small><details><summary>Why work lands here</summary><p>Local routing phrases: ${esc(s.keywords.join(', ')||'None — manual routing only')}.</p><p>${s.requiredInputs.length?'Helpful input: '+esc(s.requiredInputs.join('; '))+'. ':''}Multiple matches stay in the inbox. These rules are evidence, not a model confidence score.</p></details></div><div class="inline-actions">${button(s.enabled?'Pause new routing':'Enable routing','toggle-skill',s.id,'secondary')}${button('Export manifest','export-skill',s.id,'secondary')}${!state.tasks.some(t=>t.skillId===s.id)?button('Remove unused skill','remove-skill',s.id,'subtle'):''}</div><h3>Tasks currently here</h3>${taskList(state.tasks.filter(t=>t.skillId===s.id&&active(t)))}`,true);}
function taskDrawer(id){const t=findTask(id);if(!t)return;focused=id;const s=skillFor(t), d=$('#dialog');
 showDialog(t.title,`<div class="task-meta"><span class="status-pill ${t.status}">${LABELS[t.status]}</span>${t.sample?'<span class="sample">FICTIONAL WALKTHROUGH</span>':''}<span class="quiet">${esc(s?.name||'Unrouted')}</span></div><div class="source-meta">From ${esc(t.source)}${t.sourceUrl?` · <a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}<br><small>${esc(stamp(t.createdAt))} · Revision ${t.revision}</small></div><details class="source-box" ${!t.result?'open':''}><summary>Source & context <span>Read before sharing</span></summary><pre>${esc(t.body)}</pre>${t.status!=='closed'?button('Correct source text','edit-source',t.id,'text-button'):''}</details><div class="route-explanation">${icon('fork')}<span>${esc(t.route.reason)}</span></div>${journeyStrip(t)}${!t.skillId||t.status==='triage'?`<form data-form="route" data-id="${t.id}" data-revision="${t.revision}"><label class="field">Which skill should handle this?<select name="skillId" required><option value="">Choose a skill…</option>${state.skills.filter(sk=>sk.enabled).map(sk=>`<option value="${sk.id}">${esc(sk.name)}</option>`).join('')}</select></label><button class="primary" type="submit">Route task</button></form>`:''}${t.status==='closed'?`<div class="notice">Closed in this board. No outside action is asserted.</div>${button('Reopen task','reopen',t.id,'secondary')}`:t.skillId?`<section class="decision-summary"><span class="eyebrow">WHAT WILL HAPPEN</span><h3>A draft. Not an action.</h3><p>${esc(s.instructions)}</p><div class="boundary">${icon('shield')} No emails sent. No systems changed. No money moved.</div></section>${t.steering?`<div class="notice"><strong>Your direction:</strong> ${esc(t.steering)}</div>`:''}${busy?.id===t.id?`<div class="running" role="status"><span class="spinner"></span>Request in progress. Waiting for ${provider.name}… ${button('Cancel request','cancel-run',t.id,'secondary')}</div>`:''}${t.status==='blocked'?`<div class="notice danger">${esc(state.audit.find(a=>a.taskId===t.id&&a.message.startsWith('Blocked:'))?.message||'This task needs attention.')}</div>${button('Return to preparation','retry',t.id,'secondary')}`:''}${!busy&&['ready','awaiting','blocked'].includes(t.status)?`<section class="prepare-actions"><h3>How would you like to prepare it?</h3><div class="direction-chips" role="group" aria-label="Preparation direction">${button('Prepare the usual output','direction-default',t.id,'direction-chip')}${button('Ask what is missing first','direction-clarify',t.id,'direction-chip')}${button('Make a handoff brief','direction-handoff',t.id,'direction-chip')}</div><p class="small-copy">${t.sensitivity==='private'?'This source is private. Local preparation is available; AI handoff stays locked until you review sharing.':'Marked shareable by you. Only this task, its skill contract, and prior reviewed journey stages will be included.'}</p><div class="choice-grid">${button(`${icon('copy')}<strong>Use ${provider.name}</strong><small>Copy a request into your own chat</small>`,'handoff',t.id,'choice')}${button(`${icon('list')}<strong>Make a local brief</strong><small>Structure the source. No AI call.</small>`,'local-brief',t.id,'choice')}</div>${api.configured?button(`${icon('arrow')} Generate draft via API`,'generate',t.id,'secondary full'):''}${t.sensitivity==='private'?button('Review sharing permission','sharing',t.id,'text-button'):button('Make private again','make-private',t.id,'text-button')}<details class="paste-result" ${t.status==='awaiting'?'open':''}><summary>Already have a draft? Bring it back.</summary><form data-form="result" data-id="${t.id}" data-revision="${t.revision}"><label class="field">Paste the response<textarea name="result" required maxlength="28000" rows="7" placeholder="Paste plain text or the complete JSON response…"></textarea></label><button class="primary" type="submit">Bring draft in for review</button></form></details></section>`:''}${t.result?resultPanel(t):''}<details class="steering"><summary>Other direction? Steer this task.</summary><form data-form="revise" data-id="${t.id}" data-revision="${t.revision}"><label class="field">What should change?<textarea name="steering" required maxlength="2000" rows="3" placeholder="For example: acknowledge the delay, but do not promise a new date.">${esc(t.steering)}</textarea></label><small>Changing direction removes the old draft and its approval. A new result needs a new review.</small><button class="secondary" type="submit">Apply direction & prepare again</button></form></details><details class="steering"><summary>Route or owner</summary><form data-form="route" data-id="${t.id}" data-revision="${t.revision}"><label class="field">Change skill<select name="skillId">${state.skills.filter(sk=>sk.enabled).map(sk=>`<option value="${sk.id}" ${sk.id===t.skillId?'selected':''}>${esc(sk.name)}</option>`).join('')}</select></label><button type="submit" class="secondary">Reroute current stage & clear draft</button></form><form data-form="assign" data-id="${t.id}" data-revision="${t.revision}"><label class="field">Local owner label<select name="ownerId"><option value="">Unassigned</option>${state.people.map(p=>`<option value="${p.id}" ${p.id===t.ownerId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button type="submit" class="secondary">Save owner label</button></form></details>`:''}<div class="drawer-footer">${button('Export task','export-task',t.id,'subtle')}${t.status!=='closed'?button('Close task','close-task',t.id,'subtle'):''}<small>Closing or exporting does not execute the plan.</small></div>`,true);focused=id;d.dataset.taskId=id;}
function resultPanel(t){const canContinue=t.status==='approved'&&state.skills.some(sk=>sk.enabled&&sk.id!==t.skillId);return `<section class="result-panel"><div class="section-heading"><h3>${t.status==='approved'?'Your approved draft':'Review the draft'}</h3><span class="evidence-badge">${esc(t.provenance?.kind==='api'?'API response':t.provenance?.kind==='sample'?'Sample fixture':t.provenance?.kind==='local'?'Local brief':'Pasted result')}</span></div><p>${esc(t.result.summary)}</p><small class="provenance">${esc(t.provenance?.label||'Origin not verified')}</small><pre class="draft-output">${esc(t.result.draft)}</pre>${t.result.questions.length?`<div class="open-questions"><strong>Still worth checking</strong><ul>${t.result.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div>`:''}${t.status==='review'?`<form data-form="approve" data-id="${t.id}" data-revision="${t.revision}"><label class="check-label"><input type="checkbox" name="confirmed" required> I checked the draft against the source and accept it as a draft only.</label><button class="primary" type="submit">${icon('check')} Approve draft</button></form>`:t.status==='approved'?`<div class="notice success">${icon('check')} Approved here. Still not sent anywhere.</div>`:`<div class="notice">A retained draft, not an approval.</div>`}<div class="inline-actions">${button(`${icon('copy')} Copy draft`,'copy-draft',t.id,'secondary')}${button('Edit draft','edit-draft',t.id,'secondary')}${button(`${icon('download')} Download draft`,'export-task',t.id,'secondary')}${canContinue?button(`${icon('arrow')} Continue to another skill`,'continue',t.id,'secondary'):''}</div>${canContinue?'<p class="small-copy">Continue keeps this approved stage in the task journey, then moves the same task to another stable skill.</p>':''}</section>`;}
function sharing(id){const t=findTask(id);showDialog('Check before sharing.',`<p>This task is currently private. No account connection is needed to use companion mode, but pasting into ${provider.name} sends that content to its service.</p><div class="source-box"><pre>${esc(t.body)}</pre></div><p>Only this task, its current skill contract, your steering, and any prior reviewed stages in this task's journey are included. People notes and other tasks are excluded.</p><form data-form="sharing" data-id="${id}" data-revision="${t.revision}"><label class="check-label"><input type="checkbox" name="consent" required> I reviewed this content and am allowed to share it with my chosen AI service.</label><button class="primary" type="submit">Mark this task shareable</button></form><p class="fine-print">Do not use a personal account for restricted workplace data. This setting is not legal or organizational permission.</p>`);}
function handoff(id){const t=findTask(id);if(t.sensitivity!=='shareable'){sharing(id);return;}const request=makeHandoff(t,skillFor(t));showDialog(`Prepare with ${provider.name}`,`<div class="handoff-steps"><p><b>1.</b> Copy the prepared request below.</p><p><b>2.</b> Open your chat, paste it, and let ${provider.name} prepare a draft.</p><p><b>3.</b> Return to this task and paste the response for review.</p></div><textarea class="code-text" aria-label="Prepared request" readonly>${esc(request)}</textarea><div class="inline-actions">${button(`${icon('copy')} Copy request`,'copy-request',id,'primary')}<a class="button secondary" href="${provider.url}" target="_blank" rel="noopener noreferrer">Open ${provider.name} ↗</a>${button('Back to task','task',id,'secondary')}</div><p class="fine-print">Nothing is inserted into the chat automatically. Review its privacy settings and your workplace policy before pasting. A handoff is not a completed run.</p>`,true);}
function skillLibrary(){const available=CATALOG.filter(sk=>!state.skills.some(s=>s.id===sk.id));showDialog('A skill for the work you do.',`<p>Start small. These are board slots, not a ceiling on your skill library. Keep only the stable stations you actually reach for. ${state.skills.length} of 24 board slots used.</p><div class="library-grid">${available.map(sk=>`<article><span class="skill-icon">${icon(sk.icon)}</span><h3>${esc(sk.name)}</h3><p>${esc(sk.description)}</p>${button('Add skill','install-skill',sk.id,'secondary')}</article>`).join('')}</div><details class="custom-skill"><summary>Create your own skill</summary><form data-form="skill">${field('Name','name','','required maxlength="60"')}${field('Short description','description','','required maxlength="180"')}${field('Routing phrases, separated by commas','keywords','','maxlength="400" placeholder="invoice, reconciliation"')}<label class="field">What should it prepare?<textarea name="instructions" required maxlength="4000" rows="4"></textarea></label><label class="field">What must it never do?<textarea name="negativeScope" required maxlength="1000" rows="2">No sending, spending, signing, deploying, deleting, or autonomous external actions.</textarea></label><details class="contract-details"><summary>Routing & output details (optional)</summary>${field('Use this skill when…','useWhen','','maxlength="600" placeholder="A clear sentence is enough."')}${field('Do not use this skill when…','doNotUseWhen','','maxlength="600"')}${field('Helpful inputs, separated by commas','requiredInputs','','maxlength="500"')}${field('Expected output','outputContract','','maxlength="600" placeholder="A reviewable draft with open questions."')}</details><button type="submit" class="primary">Create draft-only skill</button></form></details>${button('Import a skill manifest (.json)','import-skill','','subtle')}<p class="fine-print">A skill is a stable instruction contract, not an autonomous employee. Tasks move to skills; skills do not roam the workspace or gain tool permissions.</p>`);}
async function checkApi(){if(location.protocol==='file:')return;try{const r=await fetch('../api/status',{cache:'no-store'});if(!r.ok)return;const body=await r.json();csrf=body.csrf;api=body.providers?.[edition]||{configured:false};render();}catch{/* Companion mode intentionally requires no server API. */}}
async function generate(id){const t=findTask(id);if(t.sensitivity!=='shareable'){sharing(id);return;}if(!api.configured)throw new Error('Configure your local server first, or use companion mode.');showDialog('One draft. One explicit request.',`<p>This sends only this task and its skill contract to the ${provider.name} API configured on your local server.</p><p><strong>Separate provider API charges may apply.</strong> Your chat subscription does not pay for this request. There are no automatic retries and no tools are executed.</p><p>Model: <code>${esc(api.model)}</code></p><div class="inline-actions">${button('Generate this draft','confirm-generate',id,'primary')}${button('Cancel','task',id,'secondary')}</div>`);}
async function runApi(id){if(busy)throw new Error('One API request at a time. Wait or cancel the active request.');const original=findTask(id);if(original.sensitivity!=='shareable')throw new Error('Mark this task shareable first.');await commit({type:'handoff',id,expected:original.revision});const t=findTask(id), revision=t.revision;const controller=new AbortController();busy={id,controller};taskDrawer(id);const timeout=setTimeout(()=>controller.abort('timeout'),45000);try{const response=await fetch('../api/generate',{method:'POST',headers:{'Content-Type':'application/json','X-Switchboard-CSRF':csrf},body:JSON.stringify({edition,task:t,skill:skillFor(t)}),signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.error||`Server returned ${response.status}.`);await commit({type:'result',id,expected:revision,result:data.result,kind:'api',label:`${provider.name} API · ${data.model}`});toast('Draft received. Review it against the source.');}catch(err){const reason=controller.signal.aborted?'Request cancelled or timed out. The provider may still finish or bill a request it already received.':err.message;try{const latest=findTask(id);if(latest?.revision===revision)await commit({type:'block',id,expected:revision,reason:reason.slice(0,400)});}catch{}toast(reason,true);}finally{clearTimeout(timeout);busy=null;if($('#dialog').open&&$('#dialog').dataset.taskId===id)taskDrawer(id);}}
async function action(name,id){
 if(name==='view'){view=id;query='';render();return;}
 if(name==='dismiss'){$('#dialog').close();return;}
 if(name==='capture'){capture();return;}if(name==='guide'){showDialog('From loose end to reviewed draft.',`<div class="handoff-steps"><p><b>1. Capture.</b> Paste source text or drop a .txt or .md file. Rules suggest one stable skill station; ambiguous work waits for you.</p><p><b>2. Prepare.</b> Choose a local brief, or review sharing and copy a request into ${provider.name}. Paste the response back here.</p><p><b>3. Review.</b> Check the source, edit the draft, and approve it. Nothing is sent.</p><p><b>4. Continue when useful.</b> An approved task can move to another skill. Its reviewed prior stage stays attached to the task.</p><p><b>Keep control.</b> Correcting source clears the journey; ordinary rerouting only changes the current stage. Owner labels do not notify people.</p></div><p class="fine-print">Keyboard: N captures work; / opens search; Escape closes a dialog. Nothing runs while the app is closed. This is an independent companion, not a native provider dashboard.</p>`);return;}if(name==='task'){taskDrawer(id);return;}if(name==='tile'){tileDrawer(id);return;}
 if(name==='continue'){const t=findTask(id);if(t.status!=='approved')throw new Error('Approve the current draft before continuing.');const choices=state.skills.filter(sk=>sk.enabled&&sk.id!==t.skillId);showDialog('Move this task to another skill.',`<p>The approved ${esc(skillFor(t)?.name||'current')} draft stays attached as a completed stage. The same task then moves to another stable skill station.</p><form data-form="continue" data-id="${t.id}" data-revision="${t.revision}"><label class="field">Next skill<select name="skillId" required><option value="">Choose the next skill…</option>${choices.map(sk=>`<option value="${sk.id}">${esc(sk.name)}</option>`).join('')}</select></label><div class="notice">Nothing is sent or executed. Only the task's local journey changes.</div><button class="primary" type="submit">Move task ${icon('arrow')}</button></form>`,true);return;}
 if(name.startsWith('direction-')){const t=findTask(id),directions={'direction-default':'Prepare the usual skill output. Do not invent missing facts or commitments.','direction-clarify':'Draft only the minimum questions needed to clarify missing facts before committing to a plan.','direction-handoff':'Prepare a concise handoff brief for a human colleague: context, verified facts, decision needed, and unknown owner or timing. Do not send it or assign a person without evidence.'};await commit({type:'revise',id,expected:t.revision,steering:directions[name]});taskDrawer(id);return;}
 if(name==='edit-source'){const t=findTask(id);showDialog('Correct the source, not the evidence.',`<form data-form="edit-source" data-id="${id}" data-revision="${t.revision}">${field('Title','title',t.title,'required maxlength="140"')}<label class="field">Source text<textarea name="body" required maxlength="12000" rows="8">${esc(t.body)}</textarea></label>${field('Source label','source',t.source,'required maxlength="120"')}${field('Source link','sourceUrl',t.sourceUrl,'type="url"')}<p class="small-copy">Saving resets sharing to private, clears the previous draft and approval, and rechecks the route.</p><button type="submit" class="primary">Save corrected source</button></form>`,true);return;}
 if(name==='remove-skill'){await commit({type:'removeSkill',id});$('#dialog').close();toast('Unused skill removed. Other work is unchanged.');return;}
 if(name==='filter'){filter=id;render();return;}if(name==='compact'){compact=!compact;render();return;}
 if(name==='skills'){skillLibrary();return;}if(name==='sharing'){sharing(id);return;}if(name==='handoff'){handoff(id);return;}
 if(name==='copy-request'){const t=findTask(id);if(t.sensitivity!=='shareable')throw new Error('Task sharing changed. Review permission again.');await copyText(makeHandoff(t,skillFor(t)));await commit({type:'handoff',id,expected:t.revision});return;}
 if(name==='copy-draft'){await copyText(findTask(id).result.draft);return;}
 if(name==='export-task'){const t=findTask(id);download(`switchboard-${t.id.slice(0,8)}.md`,exportTask(t,skillFor(t)));return;}
 if(name==='export'){download(`switchboard-${edition}-backup.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported. It contains your private work.');return;}
 if(name==='export-audit'){download(`switchboard-${edition}-activity.json`,JSON.stringify({notice:'Local, editable history. Not independently verified.',events:state.audit},null,2),'application/json');return;}
 if(name==='export-skill'){download(`${id}.skill.json`,JSON.stringify(state.skills.find(s=>s.id===id),null,2),'application/json');return;}
 if(name==='recovery-download'){download(`switchboard-${edition}-recovery.txt`,recoveryRaw);return;}
 if(name==='reload'){location.reload();return;}
 if(name==='check-api'){await checkApi();toast(api.configured?'Local API configuration found. No paid request made.':'Companion mode is ready. No configured local API found.');return;}
 if(name==='download-skill'){download('SKILL.md',`---\nname: skill-switchboard\ndescription: Turn incoming work into scoped draft preparation and explicit human review.\n---\n\n# Skill Switchboard for ${provider.name}\n\n${SYSTEM_PROMPT}\n\nFollow the supplied skill contract and return the requested JSON. Do not claim the local board changed unless a supported tool actually changed it. The browser companion exchanges requests and results manually. Never represent a copied request as a completed task.\n`);return;}
 if(name==='install-skill'){await commit({type:'addSkill',skill:CATALOG.find(s=>s.id===id)});skillLibrary();toast('Skill added. Existing work stays in place.');return;}
 if(name==='toggle-skill'){await commit({type:'toggleSkill',id});tileDrawer(id);return;}
 if(name==='person'){showDialog('Add a person to your context.',`<p>A local working note. No invitation will be sent.</p><form data-form="person">${field('Name','name','','required maxlength="80"')}${field('Role or responsibility','role','','maxlength="120"')}<label class="field">Useful working context<textarea name="context" maxlength="500" rows="3" placeholder="For example: confirms release readiness; prefers a short written summary."></textarea></label><button type="submit" class="primary">Save local person card</button></form>`);return;}
 if(name==='remove-person'){showDialog('Remove this local person card?',`<p>Tasks will be retained with their owner label cleared. No one will be notified.</p>${button('Remove card','confirm-remove-person',id,'danger-button')}`);return;}
 if(name==='confirm-remove-person'){await commit({type:'removePerson',id});$('#dialog').close();return;}
 if(name==='make-private'){const t=findTask(id);await commit({type:'sharing',id,expected:t.revision,value:'private'});taskDrawer(id);return;}
 if(name==='local-brief'){const t=findTask(id);await commit({type:'result',id,expected:t.revision,result:makeLocalBrief(t,skillFor(t)),kind:'local',label:'Deterministic preparation brief — no model called'});taskDrawer(id);return;}
 if(name==='edit-draft'){const t=findTask(id);showDialog('Edit before you approve.',`<form data-form="edit-result" data-id="${id}" data-revision="${t.revision}"><label class="field">Draft<textarea name="draft" required maxlength="24000" rows="16">${esc(t.result.draft)}</textarea></label><p>Saving requires a new approval. Source and questions stay attached.</p><button class="primary" type="submit">Save for review</button></form>`,true);return;}
 if(name==='retry'||name==='reopen'){const t=findTask(id);await commit({type:name,id,expected:t.revision});taskDrawer(id);return;}
 if(name==='close-task'){showDialog('Close this task?',`<p>This removes it from open work, but keeps its source and draft in the Closed view. It does not claim anything happened outside this board.</p>${button('Close in this board','confirm-close',id,'primary')}`);return;}
 if(name==='confirm-close'){const t=findTask(id);await commit({type:'close',id,expected:t.revision});$('#dialog').close();return;}
 if(name==='generate'){await generate(id);return;}if(name==='confirm-generate'){await runApi(id);return;}
 if(name==='cancel-run'){busy?.controller.abort('user');return;}
 if(name==='import'||name==='import-skill'||name==='text-file'){const el=$('#file-input');el.dataset.mode=name;el.accept=name==='text-file'?'.txt,.md':'.json';el.value='';el.click();return;}
 if(name==='prune'){showDialog('Remove closed work?',`<p>${state.tasks.filter(t=>t.status==='closed').length} closed tasks will be permanently removed from this browser. Export first to retain their content.</p>${button('Export backup','export','','secondary')}${button('Remove closed tasks','confirm-prune','','danger-button')}`);return;}
 if(name==='confirm-prune'){await commit({type:'deleteClosed'});$('#dialog').close();return;}
 if(name==='reset'){showDialog('Reset this edition?',`<p>Only the ${provider.name} board in this browser will be cleared. This cannot be undone without a backup.</p><form data-form="reset">${field('Type RESET to confirm','confirmation','','required pattern="RESET" autocomplete="off"')}<button class="danger-button" type="submit">Clear this local board</button></form>`);return;}
 if(name==='confirm-restore'){const next=restoreBackup(pendingRestore);next.revision=state.revision+1;await commit(()=>next);pendingRestore=null;$('#dialog').close();toast('Backup restored. Sharing is private and imported approvals need review.');return;}
}
let pendingRestore=null;
async function onFile(file,mode){if(!file)return;if(file.size>(mode==='text-file'?50000:LIMITS.bytes))throw new Error('File exceeds the supported size. Use a smaller text file or board backup.');const raw=await file.text();if(mode==='text-file'){if(!/\.(txt|md)$/i.test(file.name))throw new Error('Only .txt and .md source files are supported.');if(raw.length>LIMITS.body)throw new Error('Source files must be at most 12,000 characters.');if(raw.includes('\0'))throw new Error('This appears to be a binary file, not plain text.');const form=$('form[data-form="capture"]');if(form){form.elements.body.value=raw;form.elements.source.value=file.name;}else capture({title:file.name.replace(/\.(txt|md)$/i,''),body:raw,source:file.name});toast('File read locally. Review it, then capture.');return;}let data;try{data=JSON.parse(raw);}catch{throw new Error('That file is not valid JSON. Your current board is unchanged.');}if(mode==='import-skill'){await commit({type:'addSkill',skill:data});skillLibrary();return;}pendingRestore=validateState(data);showDialog('Restore this backup?',`<p>This will replace your current ${provider.name} board with ${pendingRestore.tasks.length} tasks, ${pendingRestore.skills.length} skills, and ${pendingRestore.people.length} people.</p><p>All restored tasks become private. Previously approved drafts need fresh review. No API request or external action will run.</p><div class="inline-actions">${button('Export current board first','export','','secondary')}${button('Replace with this backup','confirm-restore','','danger-button')}</div>`);}
async function submit(form,submitter){const data=Object.fromEntries(new FormData(form)), type=form.dataset.form, id=form.dataset.id, expected=Number(form.dataset.revision);
 if(type==='onboard'){if(state.onboarded&&state.tasks.length){$('#dialog').close();return;}await commit(s=>{let next=dispatch(s,{type:'onboard',pack:data.pack});if(submitter?.value==='sample')next=withSamples(next);return next;});$('#dialog').close();if(submitter?.value==='empty')capture();return;}
 if(type==='capture'){await commit({type:'addTask',...data});$('#dialog').close();taskDrawer(state.tasks[0].id);toast('Captured. No AI or external service was called.');return;}
 if(type==='person'){await commit({type:'addPerson',...data});$('#dialog').close();return;}
 if(type==='skill'){await commit({type:'addSkill',skill:{...data,id:'custom-'+newId().slice(0,8),icon:'list',keywords:data.keywords.split(',').map(k=>k.trim()).filter(Boolean),useWhen:data.useWhen||data.description,doNotUseWhen:data.doNotUseWhen||data.negativeScope,requiredInputs:(data.requiredInputs||'').split(',').map(x=>x.trim()).filter(Boolean),outputContract:data.outputContract||'A complete, reviewable draft with material unknowns called out.',effectClass:'prepare',version:1}});skillLibrary();return;}
 if(type==='continue'){await commit({type:'continue',id,expected,skillId:data.skillId});const moved=findTask(id);taskDrawer(id);toast(`Task moved to ${skillFor(moved)?.name||'the next skill'}. Prior approved stage preserved.`);return;}
 if(type==='edit-source'){await commit({type:'editSource',id,expected,...data});taskDrawer(id);return;}
 if(type==='route'){await commit({type:'route',id,expected,skillId:data.skillId});taskDrawer(id);return;}
 if(type==='assign'){await commit({type:'assign',id,expected,ownerId:data.ownerId});taskDrawer(id);return;}
 if(type==='sharing'){await commit({type:'sharing',id,expected,value:'shareable'});taskDrawer(id);toast('Marked shareable. Nothing transmitted.');return;}
 if(type==='result'){await commit({type:'result',id,expected,result:normalizeResult(data.result),kind:'pasted',label:'Pasted by user — provider origin not independently verified'});taskDrawer(id);return;}
 if(type==='edit-result'){const t=findTask(id);await commit({type:'result',id,expected,result:{...t.result,draft:data.draft},kind:'pasted',label:'Edited by user — human review required'});taskDrawer(id);return;}
 if(type==='approve'){await commit({type:'approve',id,expected,confirmed:data.confirmed==='on'});taskDrawer(id);toast('Draft approved. Nothing sent or executed.');return;}
 if(type==='revise'){await commit({type:'revise',id,expected,steering:data.steering});taskDrawer(id);return;}
 if(type==='reset'){if(data.confirmation!=='RESET')throw new Error('Type RESET to confirm.');busy?.controller.abort('reset');if(!memoryOnly)localStorage.removeItem(key);recoveryRaw='';state=createState();view='board';render();welcome();return;}
}
shell();render();
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;action(b.dataset.action,b.dataset.id).catch(err=>toast(err.message,true));});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-form]'))return;e.preventDefault();const b=e.submitter;if(b)b.disabled=true;submit(e.target,b).catch(err=>toast(err.message,true)).finally(()=>{if(b)b.disabled=false;});});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){const pos=e.target.selectionStart;query=e.target.value;render();const el=$('#task-search');el.focus();try{el.setSelectionRange(pos,pos);}catch{}}});
$('#file-input').addEventListener('change',e=>onFile(e.target.files[0],e.target.dataset.mode).catch(err=>toast(err.message,true)));
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();$('#drop-zone')?.classList.add('over');}});
document.addEventListener('dragleave',()=>$('#drop-zone')?.classList.remove('over'));
document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();$('#drop-zone')?.classList.remove('over');if(e.dataTransfer.files.length!==1){toast('Drop one text file at a time.',true);return;}onFile(e.dataTransfer.files[0],'text-file').catch(err=>toast(err.message,true));});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#dialog').open){const nodes=[...$('#dialog').querySelectorAll('button,input,textarea,select,a[href],summary,[tabindex]')].filter(n=>!n.disabled&&n.tabIndex>=0&&n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(first&&((e.shiftKey&&document.activeElement===first)||(!e.shiftKey&&document.activeElement===last)||!$('#dialog').contains(document.activeElement))){e.preventDefault();(e.shiftKey?last:first).focus();return;}}const typing=e.target.matches('input,textarea,select,[contenteditable]');if(e.key==='n'&&!typing&&!e.metaKey&&!e.ctrlKey&&!$('#dialog').open){e.preventDefault();capture();}if(e.key==='/'&&!typing&&!$('#dialog').open){e.preventDefault();view='inbox';render();$('#task-search').focus();}});
window.addEventListener('storage',e=>{if(e.key===key){changedElsewhere=true;banner();}});
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
if(!state.onboarded&&!recoveryRaw)welcome();checkApi();
